        MAP.put(UrlObfuscator.decode(new int[] { 203, 177, 133, 46, 65, 79, 63, 30, 244, 222, 245, 154, 119, 69, 50, 26, 226, 210, 253, 144, 124, 67, 33, 26, 224, 194, 185, 157, 39, 78, 40, 1, 225, 219, 240, 207, 104, 107, 83, 49 }, 164), F450);
